class Solution {
    public String generateTheString(int n) {
        StringBuilder sb = new StringBuilder();
        int cnt = (n % 2 == 1) ? n : n - 1;
        for (int i = 0; i < cnt; i++) sb.append('a');
        if (cnt != n) sb.append('b');
        return sb.toString();
    }
}

