class Solution:
    def generateTheString(self, n: int) -> str:
        res = []
        ch = ord('a')
        while n > 0:
            if n % 2 == 1:
                res.append(chr(ch) * n)
                break
            res.append(chr(ch))
            n -= 1
            ch += 1
        return ''.join(res)

