class Solution {
public:
    string generateTheString(int n) {
        string res;
        char ch = 'a';
        while (n > 0) {
            if (n % 2 == 1) { res.append(n, ch); break; }
            res += ch;
            n--; ch++;
        }
        return res;
    }
};

